	 */
	binary_stream& operator>>(std::string& data) {
		return *this >> prefixed(data);
	}

	/**
	 * @brief Deserialises an object that provides a deserialise function:
	 * auto& operator>>(auto& stream);
	 * 
	 * @param[out] data The object to be deserialised.
	 * 
