inline void enforce_read_bounds(const std::size_t read_size) {
		if(read_size > buffer_.size()) [[unlikely]] {
			set_state(stream_state::buff_limit_err);

			if(allow_throw()) {
				HEXI_THROW(buffer_underrun(read_size, total_read_, buffer_.size()));
