buffer_write* buffer() {
		return &buffer_;
	}

const buffer_write* buffer() const {
		return &buffer_;
	}

binary_stream_writer(binary_stream_writer&& rhs) noexcept
		: stream_base(rhs),
		  buffer_(rhs.buffer_), 
		  total_write_(rhs.total_write_) {
